let latest = 0;
function request(name, delay) {
  const id = ++latest;
  document.querySelector('#status').textContent = name + ' 로딩 중';
  setTimeout(() => {
    if (id !== latest) { console.log('오래된 결과 무시:', name); return; }
    document.querySelector('#status').textContent = name + ' 완료';
    console.log('화면에 적용:', name);
  }, delay);
}
